	hide()

	buttonHint.translationKey = "BUTTON_OpenLog"
	buttonHint.updateText()

	dragging = false
	scrollTimer.stop()
	endDragging()
	onHorizontalResizeButtonUp()
	onVerticalResizeButtonUp()
