var scrolledToBottom = false

func createEvent(triggerEvent, origin, type) -> CombatEvent:
	NativeRandomObserver.entry("Core/CombatLog.gd::createEvent", self, {"triggerEvent": triggerEvent, "origin": origin, "type": type})
	eventNum += 1
	NativeRandomObserver.middle("Core/CombatLog.gd::createEvent", "allocation_increment", self, { "eventNum": eventNum })

