	dict[key] = newVal
	return newVal

func dictSub(dict: Dictionary, key, val = 1) -> int:
	var val2 = dict.get(key, 0) - val
	if val2 <= 0:
		dict.erase(key)
	else:
		dict[key] = val2
	return val2

