func dictErase(dict: Dictionary, key, valueToErase) -> void :
	if key in dict:
		var arr = dict[key]
		arr.erase(valueToErase)
		if arr.empty():
			dict.erase(key)

func dictPop(dict: Dictionary, key):
	if key in dict:
		var arr = dict[key]
		var value = arr.pop_back()
		if arr.empty():
			dict.erase(key)
		return value
	else:
		return null

