	var observer7_value = rng.randf()
	NativeRandomObserver.primitive("Utility/Util.gd::flip", "randf", observer_label, [], observer7_value)
	return observer7_value <= chance

func flipPercent(chance, observer_label = "") -> bool:
	return roll(100.0, observer_label) <= chance


func flipRound(chance) -> int:
	return int(floor(chance) + int(flip(fmod(chance, 1.0))))


func flipWeighted(weights: Array) -> int:
	var sum = 0.0
	for weight in weights:
		sum += weight

	var val = rng.randf_range(0, sum)
	var subsum = 0.0
	for i in weights.size():
		subsum += weights[i]
		if subsum >= val:
			return i

	return weights.size()

